// pbStreamsLane is the enrich streams lane's ledger key (enrich's
// streamsLaneID — duplicated because that constant is unexported; cmd/
// mellifera/playback.go carries the same mirror with the same drift warning).
const pbStreamsLane = "__streams__"

// pbWorld is one composed playback world. Everything on it is a real
// production instance; tests add per-test queues over it.
type pbWorld struct {
	t       *testing.T
	st      *store.Store
	reg     *module.Registry
	mgr     *plugin.Manager
	media   *stream.Service
	srv     *httptest.Server
	baseURL string
	client  *http.Client
	token   string // admin bearer for the api surface
	root    string // artifact root (streams)
	queue   atomic.Pointer[enrich.Queue]
	scanDep scan.Deps
}

// pbNewWorld builds the composed world: a temp store + seeded modules, the
// real base-scanner and serial-scanner subprocesses, the stream Service with
// hermetic knobs, and the full api+web handler over real HTTP.
func pbNewWorld(t *testing.T) *pbWorld {
	t.Helper()
	for _, bin := range []string{"ffmpeg", "ffprobe"} {
		if _, err := exec.LookPath(bin); err != nil {
			t.Skipf("playback joint tests need %s on PATH (fixtures are generated in-process with lavfi): %v", bin, err)
		}
	}
	ctx := context.Background()
	tmp := t.TempDir()
	st, err := store.Open(ctx, filepath.Join(tmp, "pb.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	reg, err := module.Open(ctx, st)
	if err != nil {
		t.Fatalf("module.Open: %v", err)
	}

	scannerBin := buildBinary(t, tmp, "pb-base-scanner", "./plugins/base-scanner")
	serialBin := buildBinary(t, tmp, "pb-serial-scanner", "./plugins/serial-scanner")
	mgr := plugin.Open(plugin.Deps{
		MagicCookieKey:   "MELLIFERA_MAGIC_COOKIE",
		MagicCookieValue: "mellifera-plugin-v1",
		CoreVersion:      "0.1.0",
	})
	caps := []sdk.Capability{{Type: "scanner", ID: "default", ProtoService: "mellifera.scanner.v1.Scanner"}}
	for id, path := range map[string]string{"base-scanner": scannerBin, "serial-scanner": serialBin} {
		if err := mgr.Load(id, path, caps); err != nil {
			t.Fatalf("load %s: %v", id, err)
		}
		if err := mgr.Start(ctx, id); err != nil {
			t.Fatalf("start %s: %v", id, err)
		}
	}
	t.Cleanup(func() {
		stopCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		_ = mgr.Stop(stopCtx, "base-scanner")
		_ = mgr.Stop(stopCtx, "serial-scanner")
	})

	root := filepath.Join(tmp, "streams")
	media := &stream.Service{
		Root:        root,
		Secret:      []byte("qa-playback-media-secret"),
		HeadChunk:   2 * time.Second, // hermetic head-first: the 5s fixture splits head+tail
		SegmentTime: 1 * time.Second,
		PackTimeout: 60 * time.Second,
		Original:    pbOriginalResolver(st),
	}

	w := &pbWorld{t: t, st: st, reg: reg, mgr: mgr, media: media, token: "qa-playback-admin-token", root: root}
	w.scanDep = scan.Deps{Store: st, Modules: reg, Plugins: mgr}

	// The api Deps closure mirrors cmd/mellifera/main.go (the shell is package
	// main): Scan → scan.Run over the shared Deps; Playback → Describe + Issue.
	apiH := api.New(api.Deps{
		AdminToken: w.token,
		Store:      st,
		Scan: func(ctx context.Context, libraryID int64) (scan.Result, error) {
			return scan.Run(ctx, w.scanDep, libraryID)
		},
		Playback: func(ctx context.Context, itemID string) (api.Playback, error) {
			row, err := st.GetItem(ctx, itemID)
			if err != nil {
				return api.Playback{}, err
			}
			var doc map[string]any
			if err := json.Unmarshal(row.Document, &doc); err != nil {
				return api.Playback{}, err
			}
			mode, state, playURL, sections := media.Describe(itemID, doc)
			tok, _ := media.Issue(itemID, time.Now())
			return api.Playback{Mode: mode, State: state, PlayURL: playURL, Sections: sections, Token: tok}, nil
		},
	})
	handler := web.Handler(apiH, web.Options{Media: media})
	w.srv = httptest.NewServer(handler)
	t.Cleanup(w.srv.Close)
	w.baseURL = w.srv.URL
	w.client = &http.Client{Timeout: 120 * time.Second}
	return w
}

// pbNewQueue constructs and starts the production enrich queue over the world
// with the given PackItem closure (nil = the plain real pack, mirroring
// main.go's wiring). leaseTTL <= 0 keeps the production default.
func (w *pbWorld) pbNewQueue(t *testing.T, pack func(ctx context.Context, itemID, absPath string, ffprobe map[string]any) (enrich.PackOutcome, error), leaseTTL time.Duration) *enrich.Queue {
	t.Helper()
	deps := enrich.Deps{Store: w.st, Modules: w.reg, Plugins: w.mgr}
	deps.PackItem = pack
	if pack == nil {
		deps.PackItem = func(ctx context.Context, itemID, absPath string, ffprobe map[string]any) (enrich.PackOutcome, error) {
			build, err := w.media.Pack(ctx, itemID, absPath, ffprobe)
			return enrich.PackOutcome{Playlist: build.Playlist, Nonce: build.Nonce}, err
		}
	}
	cfg := enrich.QueueConfig{Workers: 2, Backoff: time.Millisecond}
	if leaseTTL > 0 {
		cfg.LeaseTTL = leaseTTL
	}
	q := enrich.NewQueue(deps, cfg)
	if err := q.Start(context.Background()); err != nil {
		t.Fatalf("queue Start: %v", err)
	}
	w.queue.Store(q)
	t.Cleanup(q.Stop)
	return q
}

// pbEnqueue is the streams lane's real enqueue entry (the seam the frontier
// sweep and the play verb both execute through).
func (w *pbWorld) pbEnqueue(q *enrich.Queue) func(itemID string) error {
	return func(itemID string) error { return q.EnqueuePack(itemID) }
}

// pbSweep mirrors cmd/mellifera sweepFrontier's snapshot assembly: libraries →
// series → episodes → orchestrator.Frontier, then EXECUTES the jobs through
// enqueue. Returns the executed jobs for assertion.
func (w *pbWorld) pbSweep(t *testing.T, enqueue func(string) error) []orchestrator.Job {
	t.Helper()
	ctx := context.Background()
	cool := map[string]time.Time{}
	if rows, err := w.st.ListFailures(ctx); err == nil {
		for _, r := range rows {
			if r.PluginID == pbStreamsLane {
				cool[r.ItemID] = r.NextEligibleAt
			}
		}
	}
	watched := map[string]bool{}
	if rows, err := w.st.ListProgress(ctx, 10_000); err == nil {
		for _, p := range rows {
			if p.PositionSeconds > 0 {
				watched[p.ItemID] = true
			}
		}
	}
	in := orchestrator.FrontierIn{Watched: watched, Now: time.Now()}
	libs, err := w.st.ListLibraries(ctx)
	if err != nil {
		t.Fatalf("sweep ListLibraries: %v", err)
	}
	for _, l := range libs {
		series, err := w.st.QuerySeries(ctx, l.ID, "")
		if err != nil {
			t.Fatalf("sweep QuerySeries: %v", err)
		}
		for _, sr := range series {
			items, err := w.st.QueryItemsBySeries(ctx, sr, pbSeriesBacking(sr.Document))
			if err != nil {
				t.Fatalf("sweep QueryItemsBySeries: %v", err)
			}
			eps := make([]orchestrator.Episode, 0, len(items))
			for _, it := range items {
				eps = append(eps, pbEpisode(it, cool))
			}
			in.Serials = append(in.Serials, orchestrator.Serial{
				LibraryID: l.ID, StreamsEnabled: l.StreamsEnabled, Episodes: eps,
			})
		}
	}
	jobs := orchestrator.Frontier(in)
	for _, job := range jobs {
		if err := enqueue(job.ItemID); err != nil {
			t.Fatalf("sweep enqueue %s: %v", job.ItemID, err)
		}
	}
	return jobs
}

// pbEpisode mirrors cmd/mellifera episodeFromDoc: the classification gate at
// the locked opt-in default, the published-build state, the cooldown deadline.
func pbEpisode(it store.Item, cool map[string]time.Time) orchestrator.Episode {
	var doc map[string]any
	_ = json.Unmarshal(it.Document, &doc)
	ff, _ := doc["ffprobe"].(map[string]any)
	streams, _ := doc["streams"].(map[string]any)
	state, _ := streams["state"].(string)
	class := stream.Classify(ff, false)
	return orchestrator.Episode{
		ItemID:    it.ID,
		Packable:  class == stream.ClassPack || class == stream.ClassOptIn,
		Packaged:  state == stream.StatePartial || state == stream.StateComplete,
		CoolUntil: cool[it.ID],
	}
}

// pbSeriesBacking mirrors cmd/mellifera seriesBacking (same fallback).
func pbSeriesBacking(raw json.RawMessage) string {
	var doc struct {
		Parsed struct {
			Backing string `json:"backing"`
		} `json:"parsed"`
	}
	if err := json.Unmarshal(raw, &doc); err != nil || doc.Parsed.Backing == "" {
		return store.SeriesBackingDirectory
	}
	return doc.Parsed.Backing
}

// pbOriginalResolver mirrors cmd/mellifera originalResolver: the direct floor
// resolves through parsed.absolute_path and nothing else.
func pbOriginalResolver(st *store.Store) func(ctx context.Context, itemID string) (string, bool) {
	return func(ctx context.Context, itemID string) (string, bool) {
		row, err := st.GetItem(ctx, itemID)
		if err != nil {
			return "", false
		}
		var doc struct {
			Parsed struct {
				AbsolutePath string `json:"absolute_path"`
			} `json:"parsed"`
		}
		if err := json.Unmarshal(row.Document, &doc); err != nil {
			return "", false
		}
		return doc.Parsed.AbsolutePath, doc.Parsed.AbsolutePath != ""
	}
}

// pbAwaitIdle blocks until the queue has drained (pending 0, in-flight 0),
// bounded by a deadline. Polls the real Stats — no sleeps-and-hope.
func pbAwaitIdle(t *testing.T, q *enrich.Queue, timeout time.Duration) {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		s := q.Stats()
		if s.Pending == 0 && s.InFlight == 0 {
			return
		}
		time.Sleep(5 * time.Millisecond)
	}
	t.Fatalf("queue never drained: %+v (timeout %v)", q.Stats(), timeout)
}

// pbAwaitStreams polls the store until doc["streams"].state == want and
// returns the streams namespace.
func pbAwaitStreams(t *testing.T, st *store.Store, itemID, want string, timeout time.Duration) map[string]any {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		it, err := st.GetItem(context.Background(), itemID)
		if err == nil {
			var doc map[string]any
			_ = json.Unmarshal(it.Document, &doc)
			if s, ok := doc["streams"].(map[string]any); ok && s["state"] == want {
				return s
			}
		}
		time.Sleep(5 * time.Millisecond)
	}
	t.Fatalf("item %s streams state never reached %q (timeout %v)", itemID, want, timeout)
	return nil
}

// pbDo performs one HTTP exchange returning status, body bytes and response
// headers. bearer may be empty (the /media surface must work without one).
func pbDo(t *testing.T, client *http.Client, method, url, bearer string, body any) (int, []byte, http.Header) {
	t.Helper()
	buf := new(bytes.Buffer)
	if body != nil {
		if err := json.NewEncoder(buf).Encode(body); err != nil {
			t.Fatalf("encode body: %v", err)
		}
	}
	req, err := http.NewRequest(method, url, buf)
	if err != nil {
		t.Fatalf("new request %s %s: %v", method, url, err)
	}
	if bearer != "" {
		req.Header.Set("Authorization", "Bearer "+bearer)
	}
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	resp, err := client.Do(req)
	if err != nil {
		t.Fatalf("do %s %s: %v", method, url, err)
	}
	defer resp.Body.Close()
	out, rerr := io.ReadAll(resp.Body)
	if rerr != nil {
		t.Fatalf("read body %s: %v", url, rerr)
	}
	return resp.StatusCode, out, resp.Header
}

// pbPlayback is the descriptor wire shape (GET /items/{id}/playback).
type pbPlayback struct {
	Mode     string           `json:"mode"`
	State    string           `json:"state"`
	PlayURL  string           `json:"play_url"`
	Sections []map[string]any `json:"sections"`
}

// pbDescriptor fetches the descriptor and fails on any non-200.
func pbDescriptor(t *testing.T, w *pbWorld, itemID string) pbPlayback {
	t.Helper()
	status, body, _ := pbDo(t, w.client, http.MethodGet, w.baseURL+"/api/v1/items/"+itemID+"/playback", w.token, nil)
	if status != http.StatusOK {
		t.Fatalf("descriptor %s: status %d, want 200 (body=%s)", itemID, status, body)
	}
	var pb pbPlayback
	if err := json.Unmarshal(body, &pb); err != nil {
		t.Fatalf("decode descriptor %s: %v (body=%s)", itemID, err, body)
	}
	return pb
}

// pbMakeMKV generates a container-hostile fixture (h264+aac in Matroska —
// the canonical ClassPack shape) with optional container chapters. The pack
// lane's real ffmpeg remuxes it; the scanner's real ffprobe probes it.
func pbMakeMKV(t *testing.T, path string, dur time.Duration, chapters bool) {
	t.Helper()
	args := []string{
		"-f", "lavfi", "-i", "testsrc2=size=128x72:rate=10:duration=" + secs(dur),
		"-f", "lavfi", "-i", "sine=frequency=440:sample_rate=44100:duration=" + secs(dur),
	}
	if chapters {
		meta := ";FFMETADATA1\n[CHAPTER]\nTIMEBASE=1/1000\nSTART=0\nEND=2000\ntitle=Intro\n[CHAPTER]\nTIMEBASE=1/1000\nSTART=2000\nEND=5000\ntitle=Main\n"
		metaPath := path + ".meta"
		if err := os.WriteFile(metaPath, []byte(meta), 0o644); err != nil {
			t.Fatalf("write chapter metadata: %v", err)
		}
		t.Cleanup(func() { _ = os.Remove(metaPath) })
		args = append(args, "-i", metaPath, "-map", "0:v", "-map", "1:a", "-map_metadata", "2")
	} else {
		args = append(args, "-map", "0:v", "-map", "1:a")
	}
	args = append(args,
		"-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p", "-c:a", "aac",
		"-f", "matroska", path,
	)
	if b, err := exec.Command("ffmpeg", append([]string{"-nostdin", "-y"}, args...)...).CombinedOutput(); err != nil {
		t.Fatalf("ffmpeg generate %s: %v: %s", filepath.Base(path), err, b)
	}
}

func secs(d time.Duration) string { return strconv.FormatFloat(d.Seconds(), 'f', 2, 64) }

// pbWriteGarbage writes a non-video .mkv (the failing-pack fixture).
func pbWriteGarbage(t *testing.T, path string) {
	t.Helper()
	if err := os.WriteFile(path, []byte("this is not a video file, despite the extension"), 0o644); err != nil {
		t.Fatalf("write garbage fixture: %v", err)
	}
}

// pbCreateLibrary POSTs a library on any module and returns its id.
func pbCreateLibrary(t *testing.T, w *pbWorld, moduleID, root, name string) int64 {
	t.Helper()
	var resp libraryResponse
	status := doRequest(t, w.client, http.MethodPost, w.baseURL+"/api/v1/libraries", w.token,
		createLibraryRequest{ModuleID: moduleID, RootPath: root, DisplayName: name}, &resp)
	if status != http.StatusCreated {
		t.Fatalf("create library: status %d, want 201", status)
	}
	return resp.ID
}

// pbScanLibrary triggers the synchronous scan over the real api handler.
func pbScanLibrary(t *testing.T, w *pbWorld, libID int64) scanResponse {
	t.Helper()
	var resp scanResponse
	status := doRequest(t, w.client, http.MethodPost,
		fmt.Sprintf("%s/api/v1/libraries/%d/scan", w.baseURL, libID), w.token, nil, &resp)
	if status != http.StatusOK {
		t.Fatalf("scan library %d: status %d, want 200", libID, status)
	}
	return resp
}

// pbItemByRel maps a library's items by relative path over the real API.
func pbItemByRel(t *testing.T, w *pbWorld, libID int64) map[string]itemDTO {
	t.Helper()
	return indexByPath(t, listItems(t, w.client, w.baseURL, w.token, libID))
}
